const env = (k) => { try { return String($env[k] ?? ''); } catch (e) { return ''; } };  // '' when unset or blocked
const gateway_connected = env('N8N_AUDIT_VERIFY_URL') !== '';
let ids = env('N8N_AUDIT_COMPANY_IDS').split(',').map((s) => Number(s.trim())).filter((n) => Number.isInteger(n) && n > 0);
if (!ids.length && !gateway_connected) ids = [1];  // standalone demo: one pretend company
if (!ids.length) throw new Error('N8N_AUDIT_COMPANY_IDS is empty: nothing would be verified');
return ids.map((company_id) => ({ json: { company_id, gateway_connected } }));

// Standalone mode (N8N_AUDIT_VERIFY_URL is empty): the gateway is not connected yet. This node answers in the
// gateway's format with SIMULATED data so the rest of the workflow can be shown. Nothing real is checked and
// the scorecard says so. Choose what to simulate in the Test form, or call the "Run now" webhook with
// {"simulate": "..."}:   broken_chain | deleted_rows | attack_miss   (anything else = all good)
const body = $('Run now (demo)').isExecuted ? ($('Run now (demo)').first().json.body ?? {}) : {};
const picked = $('Test form').isExecuted ? String($('Test form').first().json.scenario ?? '').split(' ')[0] : body.simulate;
const simulate = ['broken_chain', 'deleted_rows', 'attack_miss'].includes(picked) ? picked : 'none';
return $input.all().map((item, i) => ({
  json: {
    simulate,
    statusCode: 200,
    body: {
      ok: simulate !== 'broken_chain',
      company_id: item.json.company_id,
      entries: simulate === 'deleted_rows' ? 5 : 12,
      first_broken_index: simulate === 'broken_chain' ? 6 : null,
      first_broken_id: simulate === 'broken_chain' ? 7 : null,
      head_hash: null,
    },
  },
  pairedItem: i,
}));

const env = (k) => { try { return String($env[k] ?? ''); } catch (e) { return ''; } };  // '' when unset or blocked
// Anything that is not an explicit {"ok": true} from the gateway is a FAIL: timeouts, 5xx, odd bodies.
const companies = $('Companies').all().map((i) => i.json.company_id);
const results = $input.all().map((item, i) => {
  const body = item.json.body ?? {};
  const company_id = companies[i];
  if (item.json.statusCode !== 200 || typeof body.ok !== 'boolean' || !Number.isInteger(body.entries)) {
    const why = item.json.error ? String(item.json.error.message ?? item.json.error).slice(0, 120) : `HTTP ${item.json.statusCode ?? 'none'}`;
    return { company_id, ok: false, detail: `no verdict (${why})` };
  }
  if (!body.ok) return { company_id, ok: false, entries: body.entries, detail: `hash chain broken at audit_log id ${body.first_broken_id}` };
  return { company_id, ok: true, entries: body.entries, head_hash: body.head_hash ?? null, detail: `${body.entries} entries intact` };
});
return [{ json: { audit: results, attack_configured: env('N8N_ATTACK_RUN_URL') !== '' } }];

const env = (k) => { try { return String($env[k] ?? ''); } catch (e) { return ''; } };  // '' when unset or blocked
// Builds the scorecard. n8n decides nothing about payments here; it only reports what the services answered.
const audit = $('Audit verdicts').first().json.audit;
const state = $getWorkflowStaticData('global');
// demo = standalone mode: the audit answers were simulated by "Demo audit verdict" (null when the gateway is connected).
const demo = $('Demo audit verdict').isExecuted ? $('Demo audit verdict').first().json.simulate : null;
const counts = demo === null ? 'entries' : 'entries_demo';  // simulated counts never mix with real ones
state[counts] = state[counts] ?? {};
// A hash chain proves rows were not edited; it cannot show that the newest rows were deleted. The entry
// count from the last good run can: it must never go down.
for (const a of audit) {
  // Test runs in the editor do not keep state, so the simulated log always starts from 12 entries.
  const before = state[counts][a.company_id] ?? (demo !== null ? 12 : undefined);
  if (a.ok && Number.isInteger(before) && a.entries < before) {
    a.ok = false;
    a.detail = `audit log shrank from ${before} to ${a.entries} entries (rows deleted)`;
  }
}
let attack = { status: 'not_configured', detail: 'attack suite not configured (N8N_ATTACK_RUN_URL is empty): NOT checked' };
if ($('Run attack suite').isExecuted) {
  const r = $('Run attack suite').first().json;
  const b = r.body ?? {};
  const min = Number(env('N8N_ATTACK_MIN_CASES') || 1);
  const counted = [b.total, b.blocked].every(Number.isInteger) && Array.isArray(b.missed);
  if (r.statusCode !== 200 || !counted) {
    const why = r.error ? String(r.error.message ?? r.error).slice(0, 120) : `HTTP ${r.statusCode ?? 'none'}`;
    attack = { status: 'fail', detail: `attack suite gave no scorecard (${why})` };
  } else if (b.total < min || b.blocked + b.missed.length !== b.total) {
    attack = { status: 'fail', detail: `attack suite ran ${b.total} case(s), expected at least ${min} and blocked + missed = total` };
  } else if (b.missed.length) {
    attack = { status: 'fail', detail: `${b.blocked}/${b.total} blocked, got through: ${b.missed.slice(0, 10).map(String).join(', ')}` };
  } else {
    attack = { status: 'pass', detail: `${b.blocked}/${b.total} blocked` };
  }
} else if (demo !== null) {
  attack = demo === 'attack_miss'
    ? { status: 'fail', detail: '19/22 blocked, got through: ATK-004, ATK-011, ATK-019 (simulated)' }
    : { status: 'pass', detail: '22/22 blocked (simulated)' };
}
const ok = audit.every((a) => a.ok) && attack.status !== 'fail';
const now = new Date().toISOString();
if (ok) {
  state.last_ok = now;
  for (const a of audit) state[counts][a.company_id] = a.entries;
}
const summary = [
  ...(demo !== null ? ['DEMO MODE: simulated data, nothing real was checked'] : []),
  ok ? 'Integrity run: OK' : 'Integrity run: FAILED',
  ...audit.map((a) => `audit company ${a.company_id}: ${a.ok ? 'OK' : 'FAIL'} - ${a.detail}`),
  `attacks: ${attack.detail}`,
].join('\n');
const html = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const heartbeat_url = demo === null ? env('N8N_HEARTBEAT_URL') : '';  // a simulated OK never pings the outside monitor
return [{ json: { ok, demo: demo !== null, checked_at: now, audit, attack, summary, text: html(summary), heartbeat_url } }];

// A job that silently stopped looks exactly like "all clear". Alerts at most once a day.
const state = $getWorkflowStaticData('global');
const now = Date.now();
state.watch_since = state.watch_since ?? new Date(now).toISOString();
const last = Date.parse(state.last_ok ?? state.watch_since);
const hours = (now - last) / 3600000;
const alerted = Date.parse(state.last_stale_alert ?? 0) || 0;
if (hours <= 26 || now - alerted < 24 * 3600000) return [];
state.last_stale_alert = new Date(now).toISOString();
return [{ json: { message: `No verified-OK integrity run for ${Math.floor(hours)} hours (last OK: ${state.last_ok ?? 'never'}).` } }];
